package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string         // PIC X len=1 = "N"
var WsC decimal.Decimal     // PIC S9(3)V99 len=5 = 0
var WsFreeze int64         // PIC 99 len=2 = 0
var WsCount int64           // PIC 99 len=2 = 0
var WsFEd string            // PIC ZZ9.9 len=5
var WsCEd string            // PIC -ZZ9.99 len=7

var tempRec TempRec
var tempFileLines []string
var tempFileIdx int

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TEMP-FILE
	if err := openTempFile(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	// CLOSE TEMP-FILE (no action needed)
	displayCounts()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func openTempFile() error {
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0
	tempFileIdx = 0
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			tempFileLines = []string{}
			return nil
		}
		return err
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Scanner strips \n and \r\n -> we already have no terminator.
		// Keep line as is (spaces are preserved except trailing? Scanner keeps spaces)
		tempFileLines = append(tempFileLines, line)
	}
	if err := scanner.Err(); err != nil {
		return err
	}
	return nil
}

func READ_PARA() {
	if tempFileIdx >= len(tempFileLines) {
		WsEofFlag = "Y"
		return
	}
	raw := tempFileLines[tempFileIdx]
	tempFileIdx++
	// pad / truncate to record length 8
	if len(raw) < 8 {
		raw = raw + strings.Repeat(" ", 8-len(raw))
	} else if len(raw) > 8 {
		raw = raw[:8]
	}
	// 05 TC-SENSOR PIC X(4) @0
	tempRec.TcSensor = raw[0:4]
	// 05 TC-F PIC 9(3)V9 @4 len=4
	field := raw[4:8]
	tempRec.TcF = parsePic9V(field, 1)
}

func parsePic9V(s string, scale int32) decimal.Decimal {
	// s contains digits only (maybe spaces). Implied decimal with scale.
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits and sign if present
	// For this file field it's unsigned digits, but be robust
	sign := ""
	if len(t) > 0 && (t[0] == '+' || t[0] == '-') {
		sign = string(t[0])
		t = t[1:]
	}
	// remove any non-digit
	digits := ""
	for _, ch := range t {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	// strip leading zeros for New but keep at least one
	n, _ := decimal.NewFromString(sign + digits)
	// implied decimal
	n = n.Shift(-scale)
	return n
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	// ROUNDED to scale of target (2 decimals)
	tmp := tempRec.TcF.Sub(decimal.NewFromInt(32)).Mul(decimal.NewFromInt(5)).Div(decimal.NewFromInt(9))
	tmp = tmp.Round(2)
	// store into PIC S9(3)V99 with truncation of high-order digits if overflow
	WsC = storeDecimal(tmp, 3, 2)

	if WsC.Sign() < 0 {
		WsFreeze++
		// PIC 99 truncation low-order digits
		WsFreeze = truncateInt(WsFreeze, 2)
	}
	WsCount++
	WsCount = truncateInt(WsCount, 2)

	WsFEd = formatNumericEdited(tempRec.TcF, "ZZ9.9")
	WsCEd = formatNumericEdited(WsC, "-ZZ9.99")

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	// TC-SENSOR is exactly 4 chars (already)
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)

	READ_PARA()
}

func displayCounts() {
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// unedited numeric PIC 99 prints zero-padded to width 2
	cStr := formatUneditedInt(WsCount, 2)
	fStr := formatUneditedInt(WsFreeze, 2)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", cStr, fStr)
}

func formatUneditedInt(v int64, digits int) string {
	// keep low-order digits
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// for signed? These are unsigned PIC 99, but handle negative similarly with sign?
	// Keep low-order digits of absolute? COBOL keeps low-order digits including sign?
	// For positive values simple modulo
	if v < 0 {
		// For negative unedited? Not needed here, but handle: keep sign? We'll just mod absolute and add sign?
		av := -v
		av = av % mod
		// COBOL would display sign? For unsigned field never negative
		v = -av
		return fmt.Sprintf("%0*d", digits, v) // will include '-'
	}
	v = v % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func truncateInt(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if v >= mod || v < 0 {
		// keep low-order digits, preserve sign for signed? Simple mod
		// For unsigned counters they never exceed 99 in test maybe but follow spec
		return v % mod
	}
	return v
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Round/truncate already done by caller if ROUNDED. Without ROUNDED caller would Truncate.
	// Now apply overflow: keep low-order digits that fit.
	// PIC S9(n)V99 means max integer digits n, scale digits.
	// Total digits = n+scale, but integer overflow means keep low-order integer digits.
	// Implementation: scale the value to integer (shift scale), then modulo 10^(n+scale)
	// Preserving sign.
	if v.IsZero() {
		return v.Truncate(scale)
	}
	sign := v.Sign()
	abs := v.Abs()
	scaled := abs.Shift(scale).Truncate(0) // integer representation of all digits
	// total digits allowed
	totalDigits := intDigits + int(scale)
	// 10^totalDigits
	mod := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := 0; i < totalDigits; i++ {
		mod = mod.Mul(ten)
	}
	// low-order digits: scaled mod mod
	// decimal mod operation
	if scaled.Cmp(mod) >= 0 {
		// scaled = scaled - floor(scaled/mod)*mod
		div := scaled.Div(mod).Truncate(0)
		scaled = scaled.Sub(div.Mul(mod))
	}
	result := scaled.Shift(-scale)
	if sign < 0 {
		result = result.Neg()
	}
	// ensure scale exactly (pad zeros)
	result = result.Truncate(scale)
	return result
}

func formatNumericEdited(v decimal.Decimal, picture string) string {
	// Determine sign handling
	signChar := ""
	body := picture
	if len(picture) > 0 && (picture[0] == '-' || picture[0] == '+') {
		signChar = string(picture[0])
		body = picture[1:]
	} else if len(picture) > 0 && (picture[len(picture)-1] == '-' || picture[len(picture)-1] == '+') {
		// trailing sign (not used in this program but handle)
		signChar = string(picture[len(picture)-1])
		body = picture[:len(picture)-1]
		// trailing sign would be at end; we treat as leading for simplicity, but need correct position
		// For this task only leading '-' occurs.
	}

	// Find dot
	dotIdx := strings.Index(body, ".")
	var intBody, fracBody string
	var fracDigits int
	if dotIdx >= 0 {
		intBody = body[:dotIdx]
		fracBody = body[dotIdx+1:]
		fracDigits = len(fracBody) // count of 9/Z after dot, but commas not expected
		// fracBody may contain ','? Not needed
	} else {
		intBody = body
		fracBody = ""
		fracDigits = 0
	}

	// integer slots count (digit positions)
	intDigitSlots := 0
	for _, ch := range intBody {
		if ch == 'Z' || ch == '9' {
			intDigitSlots++
		}
	}

	isNeg := v.Sign() < 0
	abs := v.Abs()

	// Prepare scaled integer for required fractional digits
	scaled := abs.Shift(int32(fracDigits)).Truncate(0)
	scaledStr := scaled.StringFixed(0) // no decimal point
	// scaledStr may be "0"
	if scaledStr == "" {
		scaledStr = "0"
	}
	// Remove sign if any (StringFixed for positive won't have sign)
	if len(scaledStr) > 0 && scaledStr[0] == '-' {
		scaledStr = scaledStr[1:]
	}
	// Handle decimal split
	var intStr, fracStr string
	if fracDigits == 0 {
		intStr = scaledStr
		fracStr = ""
	} else {
		if len(scaledStr) <= fracDigits {
			// need leading zeros for fractional part
			fracStr = strings.Repeat("0", fracDigits-len(scaledStr)) + scaledStr
			intStr = "0"
		} else {
			intStr = scaledStr[:len(scaledStr)-fracDigits]
			fracStr = scaledStr[len(scaledStr)-fracDigits:]
		}
	}
	if intStr == "" {
		intStr = "0"
	}
	// High-order truncation for integer part
	if len(intStr) > intDigitSlots {
		intStr = intStr[len(intStr)-intDigitSlots:]
	}

	// Build integer formatted array (same length as intBody)
	intFormatted := make([]byte, len(intBody))
	// Fill with placeholders, then assign digits
	// First copy literals (','), digit slots will be filled
	// Prepare digits queue: leading zeros for intStr shorter than intDigitSlots
	digitsForInt := intStr
	if len(digitsForInt) < intDigitSlots {
		digitsForInt = strings.Repeat("0", intDigitSlots-len(digitsForInt)) + digitsForInt
	}
	// Walk intBody from rightmost to leftmost assigning digits to digit slots
	dIdx := len(digitsForInt) - 1
	for i := len(intBody) - 1; i >= 0; i-- {
		ch := intBody[i]
		if ch == 'Z' || ch == '9' {
			if dIdx >= 0 {
				intFormatted[i] = digitsForInt[dIdx]
				dIdx--
			} else {
				intFormatted[i] = '0'
			}
		} else if ch == ',' {
			intFormatted[i] = ','
		} else {
			// '.' not in intBody, other literals
			intFormatted[i] = byte(ch)
		}
	}

	// Apply Z suppression
	suppressActive := true
	for i := 0; i < len(intBody); i++ {
		ch := intBody[i]
		if ch == ',' {
			if suppressActive {
				// check if all digit slots to the left are suppressed (already spaces) and upcoming?
				// Comma inside suppressed zone becomes space
				intFormatted[i] = ' '
			} else {
				intFormatted[i] = ','
			}
		} else if ch == 'Z' {
			if suppressActive && intFormatted[i] == '0' {
				intFormatted[i] = ' '
				// remain active
			} else {
				// non-zero digit ends suppression
				suppressActive = false
				// keep digit as is
			}
		} else if ch == '9' {
			// '9' always prints digit, ends suppression
			suppressActive = false
		}
	}

	// Build fractional part
	fracFormatted := make([]byte, len(fracBody))
	for i := 0; i < len(fracBody); i++ {
		ch := fracBody[i]
		if ch == 'Z' || ch == '9' {
			if i < len(fracStr) {
				fracFormatted[i] = fracStr[i]
			} else {
				fracFormatted[i] = '0'
			}
		} else if ch == ',' {
			fracFormatted[i] = ','
		} else {
			fracFormatted[i] = byte(ch)
		}
	}

	// Assemble body string
	var bodyStr string
	if dotIdx >= 0 {
		bodyStr = string(intFormatted) + "." + string(fracFormatted)
	} else {
		bodyStr = string(intFormatted)
	}

	if signChar != "" {
		var signOut byte
		if signChar == "-" {
			if isNeg {
				signOut = '-'
			} else {
				signOut = ' '
			}
		} else if signChar == "+" {
			if isNeg {
				signOut = '-'
			} else {
				signOut = '+'
			}
		}
		// For leading sign, prepend; for trailing sign, append (not needed here)
		// Detect if original picture had trailing sign: we stripped trailing, but we lost position
		// For this program it's leading
		if len(picture) > 0 && picture[0] == '-' || picture[0] == '+' {
			bodyStr = string(signOut) + bodyStr
		} else {
			// trailing
			bodyStr = bodyStr + string(signOut)
		}
	}
	// Ensure length equals picture length (if truncation etc)
	if len(bodyStr) < len(picture) {
		// pad on left? Should not happen because we included sign
		bodyStr = strings.Repeat(" ", len(picture)-len(bodyStr)) + bodyStr
	} else if len(bodyStr) > len(picture) {
		bodyStr = bodyStr[len(bodyStr)-len(picture):]
	}
	return bodyStr
}
